28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE = 0.1;
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	};
50	
51	const quote = (step: QuoteStep): StepResult => {
52	  const basePremium = step.items.reduce(
53	    (sum, item) => sum + BASE_PREMIUMS[item.type],
54	    0,
55	  );
56	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE;
57	  const premium = basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
58	
59	  return { premium };
60	};
61	
62	export const runScenario = (scenario: Scenario): ScenarioResult => {
63	  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
64	};
